-- Read-only one-week masked-block comparison; targets and endpoints exclude outTemp history events.
WITH sizes AS (SELECT 3600 block_s,'1h' block_type,12 expected_slots UNION ALL SELECT 21600,'6h',72 UNION ALL SELECT 86400,'24h',288), candidates AS (SELECT s.block_s,s.block_type,s.expected_slots,FLOOR((a.dateTime-1561939200)/s.block_s)*s.block_s+1561939200 block_start,COUNT(*) target_n,MIN(a.dateTime) first_t,MAX(a.dateTime) last_t FROM sizes s JOIN loucka_reconstruction.archive a ON a.dateTime>=1561939200 AND a.dateTime<1562544000 AND a.outTemp IS NOT NULL AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=a.dateTime AND c.variable='outTemp') GROUP BY s.block_s,s.block_type,s.expected_slots,block_start HAVING target_n=s.expected_slots AND first_t=block_start AND last_t=block_start+s.block_s-300), blocks AS (SELECT c.*,l.outTemp left_y,r.outTemp right_y FROM candidates c JOIN loucka_reconstruction.archive l ON l.dateTime=c.block_start-300 AND l.outTemp IS NOT NULL AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=l.dateTime AND x.variable='outTemp') JOIN loucka_reconstruction.archive r ON r.dateTime=c.block_start+c.block_s AND r.outTemp IS NOT NULL AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=r.dateTime AND x.variable='outTemp')), scores AS (SELECT b.block_type,b.block_start,t.dateTime,t.outTemp y,b.left_y+(b.right_y-b.left_y)*(t.dateTime-(b.block_start-300))/(b.block_s+300) interp,CASE WHEN r.temperature_c IS NOT NULL AND r.source_resolution='5min' AND r.quality_status='reference_only' THEN 1 ELSE 0 END ref_ok,r.temperature_c ref,(0.7886750170162296+0.9352562666974354*r.temperature_c+-0.20129399741209056*SIN(2*PI()*MOD(t.dateTime,86400)/86400)+-0.09305546547425936*COS(2*PI()*MOD(t.dateTime,86400)/86400)+-0.3075224035244028*SIN(2*PI()*(CASE WHEN t.dateTime<1577836800 THEN t.dateTime-1546300800 ELSE t.dateTime-1577836800 END)/(CASE WHEN t.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))+-1.496803043901965*COS(2*PI()*(CASE WHEN t.dateTime<1577836800 THEN t.dateTime-1546300800 ELSE t.dateTime-1577836800 END)/(CASE WHEN t.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))) ols FROM blocks b JOIN loucka_reconstruction.archive t ON t.dateTime>=b.block_start AND t.dateTime<b.block_start+b.block_s AND t.outTemp IS NOT NULL AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=t.dateTime AND x.variable='outTemp') LEFT JOIN loucka_reconstruction.reference_observations r ON r.station_id='luhamet_sehradice' AND r.observed_at_utc=t.dateTime), agg AS (SELECT block_type,block_start,COUNT(*) point_n,SUM(ref_ok) ref_n,SUM(interp-y) ie,SUM(ABS(interp-y)) ia,SUM(POW(interp-y,2)) isq,SUM(CASE WHEN ref_ok=1 THEN interp-y ELSE 0 END) iperr,SUM(CASE WHEN ref_ok=1 THEN ABS(interp-y) ELSE 0 END) ipair,SUM(CASE WHEN ref_ok=1 THEN POW(interp-y,2) ELSE 0 END) ipairsq,SUM(CASE WHEN ref_ok=1 THEN ref-y ELSE 0 END) de,SUM(CASE WHEN ref_ok=1 THEN ABS(ref-y) ELSE 0 END) da,SUM(CASE WHEN ref_ok=1 THEN POW(ref-y,2) ELSE 0 END) ds,SUM(CASE WHEN ref_ok=1 THEN ols-y ELSE 0 END) oe,SUM(CASE WHEN ref_ok=1 THEN ABS(ols-y) ELSE 0 END) oa,SUM(CASE WHEN ref_ok=1 THEN POW(ols-y,2) ELSE 0 END) os FROM scores GROUP BY block_type,block_start) SELECT block_type,COUNT(*) blocks,SUM(point_n) target_n,SUM(ref_n) reference_n,SUM(ie) interp_err_all,SUM(ia) interp_abs_all,SUM(isq) interp_sq_all,SUM(iperr) interp_err_pair,SUM(ipair) interp_abs_pair,SUM(ipairsq) interp_sq_pair,SUM(de) direct_err,SUM(da) direct_abs,SUM(ds) direct_sq,SUM(oe) ols_err,SUM(oa) ols_abs,SUM(os) ols_sq,MIN(ref_n) min_ref_per_block,MIN(point_n) min_targets_per_block FROM agg GROUP BY block_type ORDER BY block_type;
